test("checkout honours the hold queue", () => {
  const s = createStore(sample);
  placeHold(s, "b1", "m1", "2026-02-01");
  placeHold(s, "b1", "m2", "2026-02-01");
  placeHold(s, "b1", "m3", "2026-02-01");
  assert.equal(availableCopies(s, "b1"), 0);
  // Third in line, but only two copies are free.
  assert.throws(() => checkout(s, "b1", "m3", "2026-02-02"), /no copies available/);
  assert.equal(holdsFor(s, "b1").length, 3);
  // First in line takes a copy and leaves the queue.
  checkout(s, "b1", "m1", "2026-02-02");
  assert.deepEqual(holdsFor(s, "b1").map((h) => h.memberId), ["m2", "m3"]);
  assert.equal(availableCopies(s, "b1"), 0);
  // Second in line is now covered by the last free copy.
  checkout(s, "b1", "m2", "2026-02-02");
  assert.deepEqual(holdsFor(s, "b1").map((h) => h.memberId), ["m3"]);
  assert.throws(() => checkout(s, "b1", "m3", "2026-02-02"), /no copies available/);
  // Returning a copy lets the last holder in.
  checkin(s, "l5", "2026-02-03");
});

test("checkout by a non-holder uses only copies not reserved by holds", () => {
  const s = createStore(sample);
  // b3 has 3 copies and 1 open loan, so 2 are free.
  placeHold(s, "b3", "m3", "2026-02-01");
  assert.equal(availableCopies(s, "b3"), 1);
  checkout(s, "b3", "m1", "2026-02-02");
  assert.equal(availableCopies(s, "b3"), 0);
  assert.throws(() => checkout(s, "b3", "m2", "2026-02-02"), /no copies available/);
  // The hold stays put for its holder.
  assert.deepEqual(holdsFor(s, "b3").map((h) => h.memberId), ["m3"]);
});
EOF
